mapper.update:
UPDATE conversation_member
SET last_read_seq = #{seq},
    updated_at = #{now}
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND deleted = 0
  AND last_read_seq < #{seq}

UPDATE conversation_member
SET last_read_seq = LEAST(GREATEST(#{requestedSeq}, last_read_seq), #{maxSeq}),
    updated_at = #{now}
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND deleted = 0
  AND last_read_seq < LEAST(GREATEST(#{requestedSeq}, last_read_seq), #{maxSeq})

UPDATE conversation_member
SET is_last_message_recall = 1,
    updated_at = #{recalledAt}
WHERE conversation_id = #{conversationId}
  AND last_message_id = #{messageId}
  AND deleted = 0
